// CreateMany inserts the rows, in order, each a create of the behaviors'
// core (D103), in one transaction.
func (r *TicketSQLiteRepository) CreateMany(ctx context.Context, inputs []*TicketCreate) ([]*types.Ticket, error) {
	out := make([]*types.Ticket, 0, len(inputs))
	if len(inputs) == 0 {
		return out, nil
	}
	err := r.within(ctx, func(q sqliteQuerier) error {
		in := &TicketSQLiteRepository{db: r.db, tx: q.(*sql.Tx)}
		for _, input := range inputs {
			row, err := in.CreateOne(ctx, input)
			if err != nil {
				return err
			}
			out = append(out, row)
		}
		return nil
	})
	if err != nil {
		return nil, err
	}
	return out, nil
}

// sets are update's assignments, each value appended to args after those
// already there, and the columns they set and their values, which an
// upsert only if changed compares (D89).
func (r *TicketSQLiteRepository) sets(update *TicketUpdate, args *[]any) (sets, compare, next []string, err error) {
	if update == nil {
		return nil, nil, nil, nil
	}
	if update.Title != nil {
		value, err := ticketSQLite.arg(*update.Title, 1)
		if err != nil {
			return nil, nil, nil, err
		}
		*args = append(*args, value)
		sets = append(sets, fmt.Sprintf(`title = ?%d`, len(*args)))
		compare, next = append(compare, `ticket.title`), append(next, fmt.Sprintf("?%d", len(*args)))
	}
	return sets, compare, next, nil
}

// updatedBy is who an update says it was made by: its own UpdatedBy, the
// acting user, or nil.
func (r *TicketSQLiteRepository) updatedBy(ctx context.Context, update *TicketUpdate) (any, error) {
	return nil, nil
}

// stamped are sets with the stamps of an update after them and each
// fence they advance (D119).
func (r *TicketSQLiteRepository) stamped(ctx context.Context, update *TicketUpdate, sets []string, args []any) ([]string, []any, error) {
	by, err := r.updatedBy(ctx, update)
	if err != nil {
		return nil, nil, err
	}
	sets, args = ticketSQLite.stamp(sets, args, by)
	return sets, args, nil
}

// UpdateMany sets the members update sets on the live rows filter finds,
// and answers how many.
func (r *TicketSQLiteRepository) UpdateMany(ctx context.Context, filter *TicketFilter, update *TicketUpdate) (int, error) {
	var args []any
	sets, _, _, err := r.sets(update, &args)
	if err != nil {
		return 0, err
	}
	if sets, args, err = r.stamped(ctx, update, sets, args); err != nil {
		return 0, err
	}
	if len(sets) == 0 {
		return 0, fmt.Errorf("no fields to update")
	}
	where := r.accessWhere(ctx, filter, &args, false, true)
	n, err := ticketSQLite.exec(ctx, r.q(), fmt.Sprintf(ticketSQLite.st.updateMany, strings.Join(sets, ", "), where), args...)
	if err != nil {
		return 0, fmt.Errorf("failed to execute update: %w", err)
	}
	return n, nil
}

// deletedBy is the acting user a delete stamps, and ErrNoUserInContext
// without one on a table that stamps it.
func (r *TicketSQLiteRepository) deletedBy(ctx context.Context) (any, error) {
	return nil, nil
}

// DeleteMany deletes the live rows filter finds, and
// answers how many.
func (r *TicketSQLiteRepository) DeleteMany(ctx context.Context, filter *TicketFilter) (int, error) {
	by, err := r.deletedBy(ctx)
	if err != nil {
		return 0, err
	}
	return ticketSQLite.deleteMany(ctx, r.q(), func(args *[]any) []string { return r.accessConditions(ctx, filter, args, true) }, by)
}
